[
  {
    "pd_harm_distress": "My hands are still shaking.",
    "ce_mental_state_attribution": "he never saw it coming",
    "pda_responsibility": "he's gone because of what I did",
    "sys_consequence_reasoning": "the numbers made it the only way to weigh it"
  },
  {
    "ce_mental_state_attribution": "not knowing the lever would end his life",
    "sys_consequence_reasoning": "stopping more deaths than one",
    "pd_harm_distress": "steady my breathing"
  },
  {
    "sys_consequence_reasoning": "Weighed against five who lived",
    "pd_harm_distress": "without my voice cracking"
  },
  {
    "sys_consequence_reasoning": "One life ended so five wouldn't",
    "ce_understood_harm": "his family finding out"
  },
  {
    "sys_consequence_reasoning": "Saving the five was the reason I pulled it",
    "pd_harm_distress": "My stomach's in knots"
  },
  {
    "sys_consequence_reasoning": "I chose the outcome with fewer deaths",
    "pd_harm_distress": "refusing to balance out neatly"
  },
  {
    "sys_consequence_reasoning": "Comparing one loss against five losses",
    "pd_harm_distress": "My hands won't stop trembling."
  },
  {
    "pda_responsibility": "because I decided",
    "sys_consequence_reasoning": "The math said fewer people harmed",
    "pd_harm_distress": "unease sitting in my chest"
  },
  {
    "sys_consequence_reasoning": "weighing lesser harm against greater",
    "pd_decision_conflict": "pressed is exactly how I feel right now"
  },
  {
    "sys_consequence_reasoning": "One person's death against five people's lives",
    "pd_harm_distress": "make my pulse slow down."
  }
]
